/* pnstrdup (src/backend/utils/mmgr/mcxt.c): NUL-terminated palloc'd copy of
 * at most len bytes. Arena-allocated like the pstrdup shim above it. */
static char *
pnstrdup(const char *in, Size len)
{
	char	   *out;
	Size		n = strnlen(in, len);

	out = palloc(n + 1);
	memcpy(out, in, n);
	out[n] = '\0';
	return out;
}

